export function getDistrictsForProvince(provinceTh: string): ThailandDistrictItem[] {
  return THAILAND_DISTRICTS_BY_PROVINCE[provinceTh] ?? [];
}

/** Returns the capital (Mueang / Pathum Wan) or first official district display name for a province. */
export function getDefaultDistrictForProvince(provinceTh: string): string {
  const districts = getDistrictsForProvince(provinceTh);
  if (districts.length === 0) return `อำเภอเมือง${provinceTh}`;
  const preferred =
    districts.find((d) => d.nameTh === "ปทุมวัน") ??
    districts.find((d) => d.nameTh.startsWith("เมือง"));
  return (preferred ?? districts[0]).displayTh;
}

/** Normalizes a Thai district/khet name by stripping common administrative prefixes for matching. */
export function normalizeDistrictKey(district: string): string {
  return district
    .trim()
    .replace(/^(?:อำเภอ|เขต|อ\.|ข\.|เทศบาลนคร|เทศบาลเมือง|เทศบาลตำบล)\s*/u, "")
    .trim();
}

export function districtsMatch(a: string | undefined, b: string | undefined): boolean {
  if (!a || !b) return false;
  const keyA = normalizeDistrictKey(a);
  const keyB = normalizeDistrictKey(b);
  return keyA.length > 0 && keyA === keyB;
}
